// Initialize: set execution context, create execution_log row via Backend API
try {
  const body = $input.first().json;
  const credentials = body.credentials || {};
  const pipelineConfig = body.pipelineConfig || {};

  // Validate required fields
  if (!pipelineConfig.pipeline_id) throw new Error('Missing pipeline_id in pipelineConfig');
  if (!pipelineConfig.user_id) throw new Error('Missing user_id in pipelineConfig');
  if (!pipelineConfig.execution_id) throw new Error('Missing execution_id in pipelineConfig');

  // Store context for downstream nodes
  const executionContext = {
    pipeline_id: pipelineConfig.pipeline_id,
    user_id: pipelineConfig.user_id,
    execution_id: pipelineConfig.execution_id,
    niche_keyword: pipelineConfig.niche_keyword || '',
    openai_model: pipelineConfig.openai_model || 'gpt-4o-mini',
    heygen_avatar_id: pipelineConfig.heygen_avatar_id || '',
    video_language: pipelineConfig.video_language || 'en',
    script_tone: pipelineConfig.script_tone || 'professional',
    target_duration_secs: pipelineConfig.target_duration_secs || 60,
    gdrive_folder_id: pipelineConfig.gdrive_folder_id || null,
    publishing_platforms: pipelineConfig.publishing_platforms || [],
    pipeline_name: pipelineConfig.pipeline_name || '',
    internal_api_url: pipelineConfig.internal_api_url || '',
    // Credentials — in-memory only, never persisted
    credentials: {
      heygen_api_key: credentials.heygen_api_key || '',
      openai_api_key: credentials.openai_api_key || '',
      google_drive_refresh_token: credentials.google_drive_refresh_token || '',
      youtube_access_token: credentials.youtube_access_token || '',
      youtube_refresh_token: credentials.youtube_refresh_token || '',
      tiktok_access_token: credentials.tiktok_access_token || '',
      tiktok_refresh_token: credentials.tiktok_refresh_token || '',
      facebook_access_token: credentials.facebook_access_token || '',
      instagram_access_token: credentials.instagram_access_token || '',
      ayrshare_api_key: credentials.ayrshare_api_key || '',
      newsapi_api_key: credentials.newsapi_api_key || '',
      r2_access_key_id: credentials.r2_access_key_id || '',
      r2_secret_access_key: credentials.r2_secret_access_key || '',
      r2_bucket_name: credentials.r2_bucket_name || '',
      r2_endpoint: credentials.r2_endpoint || '',
    },
    // Mutable step results accumulated as workflow progresses
    stepResults: {}
  };

  return [{ json: executionContext }];
} catch (error) {
  const errMsg = error instanceof Error ? error.message : String(error);
  return [{
    json: {
      __error: true,
      __error_step: 'Initialize',
      __error_message: errMsg,
      // Pass through execution_id if available so Cleanup can finalize the log
      execution_id: ($input.first().json?.pipelineConfig?.execution_id) || null,
      internal_api_url: ($input.first().json?.pipelineConfig?.internal_api_url) || '',
      pipeline_id: ($input.first().json?.pipelineConfig?.pipeline_id) || null,
      user_id: ($input.first().json?.pipelineConfig?.user_id) || null,
    }
  }];
}

// Merge the execution context (from Initialize) with the log response.
// The Initialize node output is available from $('Initialize').first().
const ctx = $('Initialize').first().json;
return [{ json: ctx }];

// Content_Fetcher — Requirements 7.1–7.8
// Queries NewsAPI + Google News RSS for articles matching niche_keyword.
// Selects best article by keyword relevance; ties broken by recency.
// Sanitizes content: strips HTML, inline JS, tracking query params.

try {
  const ctx = $input.first().json;

  if (ctx.__error) {
    return [{ json: ctx }];
  }

  const keyword = ctx.niche_keyword || '';
  const newsApiKey = (ctx.credentials && ctx.credentials.newsapi_api_key) || '';

  // ── Helpers ──────────────────────────────────────────────────────────────

  function countOccurrences(haystack, needle) {
    if (!needle) return 0;
    let count = 0, pos = 0;
    while ((pos = haystack.indexOf(needle, pos)) !== -1) { count++; pos += needle.length; }
    return count;
  }

  function scoreArticle(article, kw) {
    if (!kw) return 0;
    const needle = kw.toLowerCase();
    const title = (article.title || '').toLowerCase();
    const body  = (article.description || article.summary || '').toLowerCase();
    return countOccurrences(title, needle) * 3 + countOccurrences(body, needle);
  }

  function sanitizeContent(text) {
    if (!text) return '';
    let r = text;
    r = r.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '');
    r = r.replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, '');
    r = r.replace(/<[^>]*>/g, '');
    r = r.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
           .replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&nbsp;/g, ' ');
    return r.replace(/\s+/g, ' ').trim();
  }

  function stripTrackingParams(url) {
    if (!url) return '';
    const TRACKING = new Set(['utm_source','utm_medium','utm_campaign','utm_content','utm_term','fbclid','gclid']);
    let parsed;
    try { parsed = new URL(url); } catch { return url; }
    const toDelete = [];
    for (const key of parsed.searchParams.keys()) {
      if (TRACKING.has(key)) toDelete.push(key);
    }
    for (const key of toDelete) parsed.searchParams.delete(key);
    return parsed.toString();
  }

  function selectBestArticle(articles, kw) {
    if (!articles || articles.length === 0) return null;
    const scored = articles.map(a => ({
      article: a,
      score: scoreArticle(a, kw),
      ts: new Date(a.publishedAt || a.pubDate || 0).getTime()
    }));
    scored.sort((a, b) => b.score !== a.score ? b.score - a.score : b.ts - a.ts);
    return scored[0].article;
  }

  function parseRss(xml, fromDate) {
    if (!xml || typeof xml !== 'string') return [];
    const items = [];
    const itemRe = /<item>([\s\S]*?)<\/item>/gi;
    let m;
    while ((m = itemRe.exec(xml)) !== null) {
      const block = m[1];
      const getTag = tag => {
        const re = new RegExp(`<${tag}(?:[^>]*)><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\/${tag}>|<${tag}(?:[^>]*)>([^<]*)<\/${tag}>`, 'i');
        const r = re.exec(block);
        if (!r) return '';
        return (r[1] !== undefined ? r[1] : r[2] || '').trim();
      };
      const title = getTag('title');
      const link  = getTag('link') || getTag('guid');
      const desc  = getTag('description');
      const pubStr = getTag('pubDate');
      const pubDate = pubStr ? new Date(pubStr) : null;
      if (fromDate && pubDate && !isNaN(pubDate) && pubDate < fromDate) continue;
      items.push({
        title,
        description: sanitizeContent(desc),
        summary: sanitizeContent(desc),
        content: '',
        url: link,
        publishedAt: (pubDate && !isNaN(pubDate)) ? pubDate.toISOString() : '',
        pubDate: (pubDate && !isNaN(pubDate)) ? pubDate.toISOString() : ''
      });
    }
    return items;
  }

  async function fetchNewsApi(kw, apiKey, from, to) {
    if (!apiKey) return [];
    const params = [
      `q=${encodeURIComponent(kw)}`,
      `from=${from.toISOString()}`,
      `to=${to.toISOString()}`,
      'language=en',
      'sortBy=publishedAt',
      'pageSize=20',
      `apiKey=${apiKey}`
    ].join('&');
    const url = `https://newsapi.org/v2/everything?${params}`;
    try {
      const resp = await $http.get(url);
      const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
      if (!data || !Array.isArray(data.articles)) return [];
      return data.articles.map(a => ({
        title: a.title || '',
        description: a.description || '',
        summary: a.description || '',
        content: a.content || '',
        url: a.url || '',
        publishedAt: a.publishedAt || ''
      }));
    } catch { return []; }
  }

  async function fetchGoogleNewsRss(kw, from) {
    const encoded = encodeURIComponent(kw);
    const url = `https://news.google.com/rss/search?q=${encoded}&hl=en-US&gl=US&ceid=US:en`;
    try {
      const xml = await $http.get(url);
      return parseRss(xml, from);
    } catch { return []; }
  }

  async function fetchAll(kw, apiKey, from, to) {
    const [newsApiResults, rssResults] = await Promise.allSettled([
      fetchNewsApi(kw, apiKey, from, to),
      fetchGoogleNewsRss(kw, from)
    ]);
    const all = [];
    if (newsApiResults.status === 'fulfilled') all.push(...newsApiResults.value);
    if (rssResults.status === 'fulfilled') all.push(...rssResults.value);
    return all;
  }

  // ── Main logic ───────────────────────────────────────────────────────────

  const now = new Date();

  // Req 7.2: Query within last 24 hours
  let articles = await fetchAll(keyword, newsApiKey, new Date(now - 24 * 3600 * 1000), now);

  // Req 7.5: Extend to 72h on no results, retry once
  if (articles.length === 0) {
    articles = await fetchAll(keyword, newsApiKey, new Date(now - 72 * 3600 * 1000), now);
  }

  // Req 7.6: Abort if still no results
  if (articles.length === 0) {
    return [{
      json: {
        ...ctx,
        __error: true,
        __error_step: 'Content_Fetcher',
        __error_message: 'no content found',
        content_fetch_status: 'failed',
        content_fetch_error: 'no content found'
      }
    }];
  }

  // Req 7.3: Select most relevant article (keyword score, tie-break by recency)
  const best = selectBestArticle(articles, keyword);

  // Req 7.4: Extract title, summary/description (preferred) or first 2,000 chars of body
  let rawContent = best.summary || best.description || '';
  if (!rawContent && best.content) rawContent = best.content.substring(0, 2000);

  // Req 7.7: Sanitize — strip HTML, inline JS
  const sanitized = sanitizeContent(rawContent);

  // Req 7.8: Abort if empty after sanitization
  if (!sanitized) {
    return [{
      json: {
        ...ctx,
        __error: true,
        __error_step: 'Content_Fetcher',
        __error_message: 'empty content after sanitization',
        content_fetch_status: 'failed',
        content_fetch_error: 'empty content after sanitization'
      }
    }];
  }

  // Req 7.7: Strip analytics tracking params from source URL
  const cleanUrl = stripTrackingParams(best.url || '');

  // Req 7.1, 7.4, logging
  return [{
    json: {
      ...ctx,
      article_title: sanitizeContent(best.title || ''),
      article_summary: sanitized,
      article_url: cleanUrl,
      content_fetch_status: 'success',
      // Logged to execution_logs (Req 7.1 / 7.2)
      stepResults: {
        ...(ctx.stepResults || {}),
        content_fetch: {
          status: 'success',
          article_url: cleanUrl
        }
      }
    }
  }];

} catch (error) {
  const errMsg = error instanceof Error ? error.message : String(error);
  const ctx = $input.first().json;
  return [{
    json: {
      ...ctx,
      __error: true,
      __error_step: 'Content_Fetcher',
      __error_message: errMsg,
      content_fetch_status: 'failed',
      content_fetch_error: errMsg
    }
  }];
}

// Script_Generator — Requirements 8.1–8.8
// Calls OpenAI Chat Completions API to generate a video script from article content.
// Uses user's openai_api_key from Vault if present; falls back to platform key.
// Retries once after 10s on API error or empty response.
// Trims script to ≤150 words at nearest sentence boundary if script > 200 words.

try {
  const ctx = $input.first().json;

  if (ctx.__error) {
    return [{ json: ctx }];
  }

  // ── Helpers ──────────────────────────────────────────────────────────────

  function countWords(text) {
    if (!text || typeof text !== 'string') return 0;
    const trimmed = text.trim();
    if (trimmed === '') return 0;
    return trimmed.split(/\s+/).length;
  }

  function truncateToSentenceBoundary(text, maxWords) {
    if (!text || typeof text !== 'string') return '';
    if (typeof maxWords !== 'number' || maxWords <= 0) return '';
    const words = text.trim().split(/\s+/);
    if (words.length <= maxWords) return text.trim();
    const candidates = words.slice(0, maxWords);
    const joined = candidates.join(' ');
    const sentenceEndRegex = /[.!?]['"\)\]]?\s*/g;
    let lastEnd = -1;
    let match;
    while ((match = sentenceEndRegex.exec(joined)) !== null) {
      lastEnd = match.index + match[0].trimEnd().length;
    }
    if (lastEnd > 0) return joined.substring(0, lastEnd).trim();
    return joined.trim();
  }

  function truncateArticleToCharLimit(text, maxChars) {
    if (!text || typeof text !== 'string') return '';
    if (text.length <= maxChars) return text;
    const candidate = text.substring(0, maxChars);
    const sentenceEndRegex = /[.!?]['"\)\]]?\s*/g;
    let lastEnd = -1;
    let match;
    while ((match = sentenceEndRegex.exec(candidate)) !== null) {
      lastEnd = match.index + match[0].trimEnd().length;
    }
    if (lastEnd > 0) return candidate.substring(0, lastEnd).trim();
    return candidate.trim();
  }

  function buildSystemPrompt() {
    return (
      'You are a professional video script writer. ' +
      'Write scripts that are factually accurate, engaging, and suitable for all audiences. ' +
      'Your scripts MUST NOT contain any copyrighted quotes or lyrics, profanity, or misinformation. ' +
      'Write in a clear, spoken-word style appropriate for an AI avatar video. ' +
      'Output only the script text with no stage directions, scene labels, or formatting markers.'
    );
  }

  function buildUserPrompt(articleTitle, articleSummary, tone, durationSecs) {
    const targetWords = Math.round((durationSecs / 60) * 140);
    return (
      `Write a ${tone} video script of approximately ${targetWords} words (target duration: ${durationSecs} seconds) ` +
      `based on the following article.\n\n` +
      `Article Title: ${articleTitle}\n\n` +
      `Article Summary:\n${articleSummary}\n\n` +
      `Requirements:\n` +
      `- Aim for exactly 130–150 words\n` +
      `- Do not include any copyrighted material, profanity, or misinformation\n` +
      `- Write in a ${tone} tone suitable for a short social media video\n` +
      `- Output only the script text, no formatting or labels`
    );
  }

  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  async function callOpenAI(apiKey, model, systemPrompt, userPrompt) {
    const url = 'https://api.openai.com/v1/chat/completions';
    const headers = {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${apiKey}`,
    };
    const body = JSON.stringify({
      model,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt },
      ],
      temperature: 0.7,
      max_tokens: 400,
    });

    async function attempt() {
      try {
        const response = await $http.request({ method: 'POST', url, headers, body });
        const data = typeof response === 'string' ? JSON.parse(response) : response;
        if (!data || !data.choices || !Array.isArray(data.choices) || data.choices.length === 0) return null;
        const content = data.choices[0]?.message?.content;
        if (!content || typeof content !== 'string' || content.trim() === '') return null;
        return content.trim();
      } catch {
        return null;
      }
    }

    // Req 8.6: First attempt
    let result = await attempt();
    if (result !== null) return result;

    // Req 8.6: Retry once after 10 seconds
    await sleep(10000);
    result = await attempt();
    if (result !== null) return result;

    // Req 8.7: Both attempts failed
    throw new Error('script generation failed');
  }

  // ── Main logic ───────────────────────────────────────────────────────────

  const articleTitle = ctx.article_title || '';
  const articleSummary = ctx.article_summary || '';
  const tone = ctx.script_tone || 'professional';
  const durationSecs = ctx.target_duration_secs || 60;
  const model = ctx.openai_model || 'gpt-4o-mini';

  // Req 8.3: Use user key if present, otherwise fall back to platform key
  const apiKey = (ctx.credentials && ctx.credentials.openai_api_key)
    ? ctx.credentials.openai_api_key
    : ($env.PLATFORM_OPENAI_API_KEY || '');

  if (!apiKey) {
    throw new Error('script generation failed');
  }

  // Req 8.1: Cap article content at 5,000 chars, truncated at nearest sentence boundary
  const cappedSummary = truncateArticleToCharLimit(articleSummary, 5000);

  // Req 8.4: System prompt prohibits copyrighted quotes, profanity, misinformation
  const systemPrompt = buildSystemPrompt();
  const userPrompt = buildUserPrompt(articleTitle, cappedSummary, tone, durationSecs);

  // Req 8.5, 8.6, 8.7: Call with retry
  let script = await callOpenAI(apiKey, model, systemPrompt, userPrompt);

  // Req 8.8: Trim if script > 200 words
  if (countWords(script) > 200) {
    script = truncateToSentenceBoundary(script, 150);
  }

  return [{
    json: {
      ...ctx,
      script_text: script,
      script_gen_status: 'success',
      stepResults: {
        ...(ctx.stepResults || {}),
        script_generation: {
          status: 'success',
          word_count: countWords(script)
        }
      }
    }
  }];

} catch (error) {
  const errMsg = error instanceof Error ? error.message : String(error);
  const ctx = $input.first().json;
  return [{
    json: {
      ...ctx,
      __error: true,
      __error_step: 'Script_Generator',
      __error_message: errMsg,
      script_gen_status: 'failed',
      script_gen_error: errMsg
    }
  }];
}

// Video_Generator — Requirements 9.1–9.9
// Calls HeyGen Video Agent API with user's heygen_api_key, avatar_id,
// video_language, and script text.
// Stores returned video_id in execution_logs (Req 9.2).
// Polls HeyGen status endpoint every 30s (max 60 polls = 30 min) (Req 9.3, 9.4).
// On 401/403: aborts with 'HeyGen API key invalid or credits exhausted' (Req 9.5).
// On 'failed': aborts with failure reason or generic fallback (Req 9.7).
// On 'completed': passes video URL to File_Stager for R2 upload (Req 9.6).
// If HeyGen key absent: aborts with 'HeyGen API key not configured' (Req 9.9).

try {
  const ctx = $input.first().json;

  if (ctx.__error) {
    return [{ json: ctx }];
  }

  // ── Helpers ──────────────────────────────────────────────────────────────

  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * Parse a HeyGen API response and return the appropriate error message,
   * or null if no error condition matched.
   */
  function parseHeyGenError(data, statusCode) {
    if (statusCode === 401 || statusCode === 403) {
      return 'HeyGen API key invalid or credits exhausted';
    }
    if (!data) return null;
    if (data.code === 40101 || data.code === 40301) {
      return 'HeyGen API key invalid or credits exhausted';
    }
    if (data.status === 401 || data.status === 403) {
      return 'HeyGen API key invalid or credits exhausted';
    }
    const videoStatus = data?.data?.status || data?.status;
    if (videoStatus === 'failed') {
      const reason =
        data?.data?.error?.message ||
        data?.data?.error ||
        data?.error?.message ||
        data?.error ||
        null;
      return reason ? String(reason) : 'HeyGen reported failure with no reason provided';
    }
    return null;
  }

  /**
   * Returns true if the HeyGen status indicates polling should continue.
   */
  function shouldRetryPoll(status) {
    return status === 'processing' || status === 'pending';
  }

  // ── Submit HeyGen video generation request (Req 9.1) ─────────────────────

  async function submitHeyGenVideo(apiKey, avatarId, videoLanguage, scriptText) {
    const url = 'https://api.heygen.com/v2/video/generate';
    const headers = {
      'Content-Type': 'application/json',
      'X-Api-Key': apiKey,
    };
    const body = JSON.stringify({
      video_inputs: [{
        character: { type: 'avatar', avatar_id: avatarId, avatar_style: 'normal' },
        voice: { type: 'text', input_text: scriptText, voice_id: '' },
      }],
      dimension: { width: 1080, height: 1920 },
      aspect_ratio: '9:16',
      language: videoLanguage || 'en',
    });

    let response;
    try {
      response = await $http.request({ method: 'POST', url, headers, body });
    } catch (err) {
      const status = err.status || err.statusCode || 0;
      const errMsg = parseHeyGenError(null, status);
      if (errMsg) throw new Error(errMsg);
      throw err;
    }

    const data = typeof response === 'string' ? JSON.parse(response) : response;
    const errMsg = parseHeyGenError(data, 0);
    if (errMsg) throw new Error(errMsg);

    const videoId = data?.data?.video_id || data?.video_id;
    if (!videoId) throw new Error('HeyGen did not return a video_id');
    return videoId;
  }

  // ── Poll HeyGen status (Req 9.3, 9.4, 9.5, 9.7) ───────────────────────

  async function pollHeyGenStatus(videoId, apiKey, maxPolls) {
    const POLL_INTERVAL_MS = 30000;
    const url = `https://api.heygen.com/v1/video_status.get?video_id=${videoId}`;
    const headers = { 'X-Api-Key': apiKey };

    for (let poll = 0; poll < maxPolls; poll++) {
      if (poll > 0) await sleep(POLL_INTERVAL_MS);

      let response;
      try {
        response = await $http.request({ method: 'GET', url, headers });
      } catch (err) {
        const status = err.status || err.statusCode || 0;
        const errMsg = parseHeyGenError(null, status);
        if (errMsg) throw new Error(errMsg);
        continue; // transient network error — continue polling
      }

      const data = typeof response === 'string' ? JSON.parse(response) : response;
      const errMsg = parseHeyGenError(data, 0);
      if (errMsg) throw new Error(errMsg);

      const videoStatus = data?.data?.status || data?.status;

      if (videoStatus === 'completed') {
        const videoUrl = data?.data?.video_url || data?.video_url;
        if (!videoUrl) throw new Error('HeyGen returned completed status but no video_url');
        return videoUrl;
      }

      if (!shouldRetryPoll(videoStatus) && videoStatus !== 'completed') {
        // Unknown non-retryable status — continue conservatively
      }
      // 'processing', 'pending', or unknown — continue polling
    }

    throw new Error('HeyGen generation timeout');
  }

  // ── Main logic ───────────────────────────────────────────────────────────

  const apiKey = ctx.credentials && ctx.credentials.heygen_api_key;

  // Req 9.9: Abort if HeyGen key not configured
  if (!apiKey) throw new Error('HeyGen API key not configured');

  const avatarId = ctx.heygen_avatar_id || '';
  const videoLanguage = ctx.video_language || 'en';
  const scriptText = ctx.script_text || '';

  // Req 9.1, 9.2: Submit and store video_id in execution context
  const videoId = await submitHeyGenVideo(apiKey, avatarId, videoLanguage, scriptText);

  // Req 9.3, 9.4, 9.5, 9.7: Poll for completion (max 60 polls = 30 min)
  const heygenVideoUrl = await pollHeyGenStatus(videoId, apiKey, 60);

  return [{
    json: {
      ...ctx,
      heygen_video_id: videoId,
      heygen_video_url: heygenVideoUrl,
      video_gen_status: 'pending_upload',
      stepResults: {
        ...(ctx.stepResults || {}),
        video_generation: {
          status: 'completed',
          heygen_video_id: videoId  // Req 9.2: video_id stored in execution_logs
        }
      }
    }
  }];

} catch (error) {
  const errMsg = error instanceof Error ? error.message : String(error);
  const ctx = $input.first().json;
  return [{
    json: {
      ...ctx,
      __error: true,
      __error_step: 'Video_Generator',
      __error_message: errMsg,
      video_gen_status: 'failed',
      video_gen_error: errMsg
    }
  }];
}

// File_Stager — Requirements 9.6, 9.8
// Downloads video from HeyGen CDN URL and uploads to Cloudflare R2.
// R2 object key: {user_id}/{pipeline_id}/{execution_id}/video.mp4 (Req 9.8)
// Retries download+upload once after 30s on failure (Req 9.6).
// Aborts with 'HeyGen video download failed' if retry also fails (Req 9.6).
// Records r2_object_key and video_file_size_bytes in execution_logs (Req 9.8).

try {
  const ctx = $input.first().json;

  if (ctx.__error) {
    return [{ json: ctx }];
  }

  // ── Helpers ──────────────────────────────────────────────────────────────

  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * Build the R2 object key for this execution.
   * Pattern: {userId}/{pipelineId}/{executionId}/video.mp4
   * (Req 9.8, Design: R2 Bucket Structure)
   */
  function buildR2ObjectKey(userId, pipelineId, executionId) {
    return `${userId}/${pipelineId}/${executionId}/video.mp4`;
  }

  // ── Validate required context ─────────────────────────────────────────────

  const heygenVideoUrl = ctx.heygen_video_url || '';
  if (!heygenVideoUrl) throw new Error('no video URL available for R2 upload');

  const userId = ctx.user_id;
  const pipelineId = ctx.pipeline_id;
  const executionId = ctx.execution_id;
  const objectKey = buildR2ObjectKey(userId, pipelineId, executionId);

  const r2AccessKeyId = ctx.credentials && ctx.credentials.r2_access_key_id;
  const r2SecretAccessKey = ctx.credentials && ctx.credentials.r2_secret_access_key;
  const r2Endpoint = ctx.credentials && ctx.credentials.r2_endpoint;
  const r2BucketName = ctx.credentials && ctx.credentials.r2_bucket_name;

  // ── Attempt download + upload (Req 9.6) ───────────────────────────────────

  async function attemptUpload() {
    try {
      // Step 1: Download video from HeyGen CDN
      const downloadResp = await $http.request({
        method: 'GET',
        url: heygenVideoUrl,
        encoding: null,
        returnFullResponse: true,
      });

      const videoBuffer = downloadResp.body;
      const fileSize = Buffer.isBuffer(videoBuffer)
        ? videoBuffer.length
        : (videoBuffer && videoBuffer.byteLength) || 0;

      // Step 2: Upload to R2 using S3-compatible PUT with AWS Signature V4
      const r2PutUrl = `${r2Endpoint}/${r2BucketName}/${objectKey}`;

      await $http.request({
        method: 'PUT',
        url: r2PutUrl,
        body: videoBuffer,
        headers: { 'Content-Type': 'video/mp4' },
        auth: {
          type: 'aws',
          accessKeyId: r2AccessKeyId,
          secretAccessKey: r2SecretAccessKey,
          region: 'auto',
          service: 's3',
        },
      });

      return { fileSize };
    } catch {
      return null;
    }
  }

  // First attempt
  let result = await attemptUpload();

  if (!result) {
    // Req 9.6: Retry once after 30 seconds
    await sleep(30000);
    result = await attemptUpload();
  }

  if (!result) {
    // Req 9.6: Both attempts failed — abort
    throw new Error('HeyGen video download failed');
  }

  // Req 9.8: Record R2 object key and file size in execution_logs
  return [{
    json: {
      ...ctx,
      r2_object_key: objectKey,
      video_file_size_bytes: result.fileSize,
      video_gen_status: 'success',
      file_stage_status: 'success',
      stepResults: {
        ...(ctx.stepResults || {}),
        file_staging: {
          status: 'success',
          r2_object_key: objectKey,          // Req 9.8
          video_file_size_bytes: result.fileSize  // Req 9.8
        }
      }
    }
  }];

} catch (error) {
  const errMsg = error instanceof Error ? error.message : String(error);
  const ctx = $input.first().json;
  return [{
    json: {
      ...ctx,
      __error: true,
      __error_step: 'File_Stager',
      __error_message: errMsg,
      file_stage_status: 'failed',
      file_stage_error: errMsg
    }
  }];
}

// Drive_Uploader — Requirements 10.1, 10.2, 10.3, 10.4, 10.5, 10.6, 10.7, 4.3, 4.5, 4.6
// Uploads staged video from R2 to user's Google Drive folder.
// Drive failure is NON-BLOCKING — Social_Publisher always continues.
// Triggers R2 object deletion within 60 minutes of upload attempt completion.

try {
  const ctx = $input.first().json;

  // Non-critical: if upstream error, clear __error and record drive as skipped.
  // Social_Publisher must always run regardless.
  if (ctx.__error) {
    return [{
      json: {
        ...ctx,
        __error: false,
        drive_upload_status: 'failed',
        drive_upload_error: `Skipped due to upstream error in ${ctx.__error_step}: ${ctx.__error_message}`,
        stepResults: {
          ...(ctx.stepResults || {}),
          drive_upload: {
            status: 'failed',
            error: `Skipped due to upstream error in ${ctx.__error_step}: ${ctx.__error_message}`
          }
        }
      }
    }];
  }

  // ── Helpers ──────────────────────────────────────────────────────────────

  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * Sanitize a pipeline name for use as a filename component.
   * Replaces characters invalid in filenames with underscores.
   */
  function sanitizePipelineName(name) {
    if (!name || typeof name !== 'string') return 'Pipeline';
    let s = name.replace(/[\/\\:*?"<>|]/g, '_');
    s = s.replace(/[\r\n\t]/g, '_');
    s = s.replace(/_+/g, '_');
    s = s.replace(/^[_\s]+|[_\s]+$/g, '');
    return s || 'Pipeline';
  }

  /**
   * Build Drive filename: [PipelineName]_[YYYY-MM-DD]_[HH-MM].mp4  (Req 10.2)
   */
  function buildDriveFileName(pipelineName, executionTimestamp) {
    const safe = sanitizePipelineName(pipelineName);
    let date = (executionTimestamp instanceof Date) ? executionTimestamp
      : (executionTimestamp ? new Date(executionTimestamp) : new Date());
    if (isNaN(date.getTime())) date = new Date();
    const yyyy = date.getUTCFullYear();
    const mm   = String(date.getUTCMonth() + 1).padStart(2, '0');
    const dd   = String(date.getUTCDate()).padStart(2, '0');
    const hh   = String(date.getUTCHours()).padStart(2, '0');
    const min  = String(date.getUTCMinutes()).padStart(2, '0');
    return `${safe}_${yyyy}-${mm}-${dd}_${hh}-${min}.mp4`;
  }

  /**
   * Returns true if the error indicates folder not found / inaccessible (Req 10.7).
   */
  function isDriveFolderError(error) {
    if (!error) return false;
    const numericStatus = error.status || error.statusCode
      || (typeof error.code === 'number' ? error.code : null);
    if (numericStatus === 404 || numericStatus === 403) return true;
    if (error.errors && Array.isArray(error.errors)) {
      for (const e of error.errors) {
        const reason = (e.reason || '').toLowerCase();
        if (reason === 'notfound' || reason === 'forbidden' || reason === 'insufficientpermissions'
            || e.code === 404 || e.code === 403) return true;
      }
    }
    const msg = ((error.message || '') + ' ' + (error.reason || '') + ' '
      + (typeof error.code === 'string' ? error.code : '')).toLowerCase();
    return msg.includes('not found') || msg.includes('notfound') || msg.includes('404')
      || msg.includes('forbidden') || msg.includes('403') || msg.includes('permission denied')
      || msg.includes('insufficient permission') || msg.includes('folder not found')
      || msg.includes('does not exist');
  }

  /**
   * Exchange Google OAuth refresh token for access token (Req 4.3, 4.5).
   * Throws on any failure — caller records error and aborts upload (not pipeline).
   */
  async function exchangeGoogleRefreshToken(refreshToken) {
    if (!refreshToken) throw new Error('Google Drive authorization expired');
    const params = new URLSearchParams({
      grant_type: 'refresh_token',
      refresh_token: refreshToken,
      client_id: $env.GOOGLE_CLIENT_ID || '',
      client_secret: $env.GOOGLE_CLIENT_SECRET || '',
    });
    let response;
    try {
      response = await $http.request({
        method: 'POST',
        url: 'https://oauth2.googleapis.com/token',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: params.toString(),
      });
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      throw new Error(`Google Drive authorization expired: ${msg}`);
    }
    const data = typeof response === 'string' ? JSON.parse(response) : response;
    if (data && data.error) {
      throw new Error(`Google Drive authorization expired: ${data.error_description || data.error}`);
    }
    const accessToken = data && (data.access_token || data.accessToken);
    if (!accessToken) throw new Error('Google Drive authorization expired: no access token in response');
    return accessToken;
  }

  /**
   * Download video data from R2 using the S3-compatible GET.
   */
  async function downloadFromR2(r2Endpoint, r2BucketName, r2ObjectKey, r2AccessKeyId, r2SecretAccessKey) {
    const url = `${r2Endpoint}/${r2BucketName}/${r2ObjectKey}`;
    const response = await $http.request({
      method: 'GET',
      url,
      encoding: null,
      returnFullResponse: true,
      auth: {
        type: 'aws',
        accessKeyId: r2AccessKeyId,
        secretAccessKey: r2SecretAccessKey,
        region: 'auto',
        service: 's3',
      },
    });
    return response.body;
  }

  /**
   * Upload video data to Google Drive folder using multipart upload.
   * Returns { fileId, webViewLink } (Req 10.3).
   */
  async function uploadToGoogleDrive(accessToken, folderId, fileName, videoData) {
    // Use multipart upload: metadata + binary in one request
    const metadata = JSON.stringify({
      name: fileName,
      parents: [folderId],
    });

    // Build multipart/related body
    const boundary = '-------n8nDriveUploadBoundary314159';
    const delimiter = `\r\n--${boundary}\r\n`;
    const closeDelimiter = `\r\n--${boundary}--`;

    // Multipart body: metadata part + media part
    const metaPart = `${delimiter}Content-Type: application/json; charset=UTF-8\r\n\r\n${metadata}`;
    const mediaPart = `${delimiter}Content-Type: video/mp4\r\n\r\n`;

    // Combine: metadata + media binary + close
    // n8n $http supports Buffer concatenation via binary-aware mode
    const metaBuffer = Buffer.from(metaPart, 'utf8');
    const mediaHeaderBuffer = Buffer.from(mediaPart, 'utf8');
    const closeBuffer = Buffer.from(closeDelimiter, 'utf8');
    const videoBuffer = Buffer.isBuffer(videoData) ? videoData : Buffer.from(videoData);
    const bodyBuffer = Buffer.concat([metaBuffer, mediaHeaderBuffer, videoBuffer, closeBuffer]);

    const uploadResp = await $http.request({
      method: 'POST',
      url: 'https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,webViewLink',
      headers: {
        'Authorization': `Bearer ${accessToken}`,
        'Content-Type': `multipart/related; boundary="${boundary}"`,
        'Content-Length': String(bodyBuffer.length),
      },
      body: bodyBuffer,
      returnFullResponse: true,
    });

    const respData = typeof uploadResp.body === 'string'
      ? JSON.parse(uploadResp.body)
      : uploadResp.body;

    if (!respData || !respData.id) {
      // Surface any Drive error for folder detection
      const driveErr = new Error(
        (respData && (respData.error && (respData.error.message || JSON.stringify(respData.error))))
          || 'Google Drive upload returned no file ID'
      );
      if (respData && respData.error && respData.error.code) {
        driveErr.status = respData.error.code;
      }
      if (respData && respData.error && Array.isArray(respData.error.errors)) {
        driveErr.errors = respData.error.errors;
      }
      throw driveErr;
    }

    return {
      fileId: respData.id,
      webViewLink: respData.webViewLink || `https://drive.google.com/file/d/${respData.id}/view`,
    };
  }

  /**
   * Delete R2 object — called after upload attempt (success or failure).
   * Failures are swallowed; a fallback R2 lifecycle rule handles cleanup.
   * (Req 10.6: within 60 minutes of upload attempt completion)
   */
  async function deleteFromR2(r2Endpoint, r2BucketName, r2ObjectKey, r2AccessKeyId, r2SecretAccessKey) {
    try {
      await $http.request({
        method: 'DELETE',
        url: `${r2Endpoint}/${r2BucketName}/${r2ObjectKey}`,
        auth: {
          type: 'aws',
          accessKeyId: r2AccessKeyId,
          secretAccessKey: r2SecretAccessKey,
          region: 'auto',
          service: 's3',
        },
      });
    } catch (_) {
      // Non-fatal — R2 lifecycle rule (24h) acts as fallback
    }
  }

  // ── Main logic ───────────────────────────────────────────────────────────

  const refreshToken  = ctx.credentials && ctx.credentials.google_drive_refresh_token;
  const folderId      = ctx.gdrive_folder_id || null;
  const pipelineName  = ctx.pipeline_name || '';
  const execTimestamp = ctx.started_at || new Date().toISOString();
  const r2ObjectKey   = ctx.r2_object_key || '';

  const r2AccessKeyId     = (ctx.credentials && ctx.credentials.r2_access_key_id) || '';
  const r2SecretAccessKey = (ctx.credentials && ctx.credentials.r2_secret_access_key) || '';
  const r2Endpoint        = (ctx.credentials && ctx.credentials.r2_endpoint) || '';
  const r2BucketName      = (ctx.credentials && ctx.credentials.r2_bucket_name) || '';

  // Req 4.3: Exchange refresh token — abort upload step only, NOT the pipeline
  let accessToken;
  try {
    accessToken = await exchangeGoogleRefreshToken(refreshToken);
  } catch (tokenErr) {
    const errMsg = tokenErr instanceof Error ? tokenErr.message : String(tokenErr);
    // Req 10.6: Trigger R2 deletion even on token failure
    await deleteFromR2(r2Endpoint, r2BucketName, r2ObjectKey, r2AccessKeyId, r2SecretAccessKey);
    return [{
      json: {
        ...ctx,
        drive_upload_status: 'failed',
        gdrive_file_id: null,
        gdrive_link: null,
        drive_upload_error: errMsg,
        stepResults: {
          ...(ctx.stepResults || {}),
          drive_upload: { status: 'failed', error: errMsg }
        }
      }
    }];
  }

  // If no Drive folder configured, skip but still clean up R2
  if (!folderId) {
    await deleteFromR2(r2Endpoint, r2BucketName, r2ObjectKey, r2AccessKeyId, r2SecretAccessKey);
    return [{
      json: {
        ...ctx,
        drive_upload_status: 'skipped',
        gdrive_file_id: null,
        gdrive_link: null,
        drive_upload_error: 'no Google Drive folder configured',
        stepResults: {
          ...(ctx.stepResults || {}),
          drive_upload: { status: 'skipped' }
        }
      }
    }];
  }

  // Build filename (Req 10.2)
  const fileName = buildDriveFileName(pipelineName, execTimestamp);

  // ── Attempt upload with retry (Req 10.4) ────────────────────────────────

  async function attemptUpload() {
    const videoData = await downloadFromR2(r2Endpoint, r2BucketName, r2ObjectKey, r2AccessKeyId, r2SecretAccessKey);
    return uploadToGoogleDrive(accessToken, folderId, fileName, videoData);
  }

  let driveResult;
  try {
    driveResult = await attemptUpload();
    // Success — record result (Req 10.3)
    const result = {
      drive_upload_status: 'success',
      gdrive_file_id: driveResult.fileId,
      gdrive_link: driveResult.webViewLink,
      drive_upload_error: null,
    };
    // Req 10.6: Trigger R2 deletion after successful upload
    await deleteFromR2(r2Endpoint, r2BucketName, r2ObjectKey, r2AccessKeyId, r2SecretAccessKey);
    return [{
      json: {
        ...ctx,
        ...result,
        stepResults: {
          ...(ctx.stepResults || {}),
          drive_upload: {
            status: 'success',
            gdrive_file_id: driveResult.fileId,
            gdrive_link: driveResult.webViewLink
          }
        }
      }
    }];
  } catch (firstErr) {
    // Req 10.7: Folder not found/inaccessible — abort without retry
    if (isDriveFolderError(firstErr)) {
      await deleteFromR2(r2Endpoint, r2BucketName, r2ObjectKey, r2AccessKeyId, r2SecretAccessKey);
      return [{
        json: {
          ...ctx,
          drive_upload_status: 'failed',
          gdrive_file_id: null,
          gdrive_link: null,
          drive_upload_error: 'destination folder not found or inaccessible',
          stepResults: {
            ...(ctx.stepResults || {}),
            drive_upload: { status: 'failed', error: 'destination folder not found or inaccessible' }
          }
        }
      }];
    }

    // Req 10.4: Retry once after 30 seconds
    await sleep(30000);

    try {
      driveResult = await attemptUpload();
      const result = {
        drive_upload_status: 'success',
        gdrive_file_id: driveResult.fileId,
        gdrive_link: driveResult.webViewLink,
        drive_upload_error: null,
      };
      await deleteFromR2(r2Endpoint, r2BucketName, r2ObjectKey, r2AccessKeyId, r2SecretAccessKey);
      return [{
        json: {
          ...ctx,
          ...result,
          stepResults: {
            ...(ctx.stepResults || {}),
            drive_upload: {
              status: 'success',
              gdrive_file_id: driveResult.fileId,
              gdrive_link: driveResult.webViewLink
            }
          }
        }
      }];
    } catch (retryErr) {
      // Req 10.5: Log error and continue — drive failure is NON-BLOCKING
      const errMsg = retryErr instanceof Error ? retryErr.message : String(retryErr);
      const finalErrMsg = isDriveFolderError(retryErr)
        ? 'destination folder not found or inaccessible'
        : errMsg;
      await deleteFromR2(r2Endpoint, r2BucketName, r2ObjectKey, r2AccessKeyId, r2SecretAccessKey);
      return [{
        json: {
          ...ctx,
          drive_upload_status: 'failed',
          gdrive_file_id: null,
          gdrive_link: null,
          drive_upload_error: finalErrMsg,
          stepResults: {
            ...(ctx.stepResults || {}),
            drive_upload: { status: 'failed', error: finalErrMsg }
          }
        }
      }];
    }
  }

} catch (error) {
  // Drive upload is NON-BLOCKING — clear __error, log failure, continue to Social_Publisher
  const errMsg = error instanceof Error ? error.message : String(error);
  const ctx = $input.first().json;
  return [{
    json: {
      ...ctx,
      __error: false,
      drive_upload_status: 'failed',
      gdrive_file_id: null,
      gdrive_link: null,
      drive_upload_error: errMsg,
      stepResults: {
        ...(ctx.stepResults || {}),
        drive_upload: { status: 'failed', error: errMsg }
      }
    }
  }];
}

// Social_Publisher — Requirements 11.1–11.10, 5.9, 5.10
//
// Publishes the completed video to each configured social platform.
// Routing decisions are made at runtime by querying the platform_audit_status
// table via the Backend API:
//   - audit_approved=false  → route through Ayrshare /post (Req 5.9, 11.9)
//   - audit_approved=true   → route through direct platform API (Req 5.10)
//
// Platform-specific rules:
//   YouTube:   visibility 'private' during audit → user preference post-audit (Req 11.2)
//   TikTok:    privacy 'SELF_ONLY' during audit → user preference post-audit (Req 11.3)
//              ai_generated_content: true always (Req 11.4)
//   Facebook:  post as Reel to connected Page (Req 11.5)
//   Instagram: post as Reel via container/publish workflow (Req 11.6)
//
// Captions are AI-generated per platform (GPT). Length limits (Req 11.7):
//   YouTube title ≤ 100 chars; TikTok/FB/IG captions ≤ 2,200 chars.
//   If caption generation fails, publishing continues with empty caption.
//
// Per-platform failure is non-blocking (Req 11.8).
// If no video URL: all platforms skipped with 'skipped: no video' (Req 11.1).
// If all platforms fail: social_publish_status = 'failed' (Req 11.10).

try {
  const ctx = $input.first().json;

  // ── Helpers ──────────────────────────────────────────────────────────────

  function sleep(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
  }

  /**
   * Enforce platform caption/title character limit (Req 11.7).
   *   youtube  → 100 chars  (title field)
   *   tiktok   → 2,200 chars
   *   facebook → 2,200 chars
   *   instagram→ 2,200 chars
   */
  function enforceCaptionLimit(caption, platform) {
    if (caption == null) return '';
    const text = String(caption);
    const limits = { youtube: 100, tiktok: 2200, facebook: 2200, instagram: 2200 };
    const limit = limits[(platform || '').toLowerCase()] !== undefined
      ? limits[(platform || '').toLowerCase()]
      : 2200;
    return text.length <= limit ? text : text.slice(0, limit);
  }

  /**
   * Returns true if every platform in results has status === 'failed' (Req 11.10).
   */
  function isAllFailed(results) {
    const entries = Object.values(results || {});
    if (entries.length === 0) return false;
    return entries.every((r) => r && r.status === 'failed');
  }

  /**
   * Determine overall publish status (Req 11.10):
   *   'failed'  → all platforms failed
   *   'success' → all actionable platforms succeeded
   *   'partial' → mixed results
   *   'skipped' → all platforms skipped
   */
  function determinePublishStatus(results) {
    const entries = Object.values(results || {});
    if (entries.length === 0) return 'skipped';
    const statuses = entries.map((r) => (r && r.status) || 'failed');
    if (statuses.every((s) => s === 'skipped' || s.startsWith('skipped:'))) return 'skipped';
    const actionable = statuses.filter((s) => s !== 'skipped' && !s.startsWith('skipped:'));
    if (actionable.length === 0) return 'skipped';
    if (actionable.every((s) => s === 'failed')) return 'failed';
    if (actionable.every((s) => s === 'success')) return 'success';
    return 'partial';
  }

  /**
   * Query the Backend API to get audit status for a platform.
   * Returns { audit_approved: boolean, youtube_visibility: string,
   *           tiktok_privacy: string } or null on failure.
   */
  async function getPlatformAuditStatus(platform, internalApiUrl) {
    try {
      const resp = await $http.request({
        method: 'GET',
        url: `${internalApiUrl}/internal/platform-audit-status/${encodeURIComponent(platform)}`,
        headers: {
          'Authorization': `Bearer ${$env.N8N_SERVICE_TOKEN || ''}`,
          'Content-Type': 'application/json',
        },
      });
      const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
      return data || null;
    } catch {
      // Default to audit period (safe) if query fails
      return { audit_approved: false };
    }
  }

  /**
   * Generate an AI-assisted caption for a platform using GPT (Req 11.7).
   * Returns the caption string, or '' if generation fails (non-blocking).
   */
  async function generateCaption(platform, articleTitle, articleUrl, scriptText, openaiApiKey, openaiModel) {
    try {
      const isYouTube = platform === 'youtube';
      const limit = isYouTube ? 100 : 2200;
      const hashtagNote = 'Include up to 30 relevant hashtags.';
      const systemPrompt = isYouTube
        ? 'You are a YouTube video title writer. Write concise, engaging titles under 100 characters. Output only the title text.'
        : `You are a social media caption writer for ${platform}. Write an engaging caption under ${limit} characters. ${hashtagNote} End with: Source: ${articleUrl}. Output only the caption text.`;
      const userPrompt = isYouTube
        ? `Write a YouTube title for this video about: ${articleTitle}. Source: ${articleUrl}`
        : `Write a ${platform} caption for a video about: ${articleTitle}\n\nScript excerpt: ${(scriptText || '').slice(0, 300)}`;

      const resp = await $http.request({
        method: 'POST',
        url: 'https://api.openai.com/v1/chat/completions',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${openaiApiKey}`,
        },
        body: JSON.stringify({
          model: openaiModel || 'gpt-4o-mini',
          messages: [
            { role: 'system', content: systemPrompt },
            { role: 'user', content: userPrompt },
          ],
          temperature: 0.7,
          max_tokens: 300,
        }),
      });
      const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
      const raw = data?.choices?.[0]?.message?.content || '';
      return enforceCaptionLimit(raw.trim(), platform);
    } catch {
      return '';
    }
  }

  // ── Ayrshare publish (Req 5.9, 11.9) ────────────────────────────────────

  /**
   * Publish via Ayrshare /post endpoint during audit period.
   * Returns { ayrshare_post_id: string } on success, throws on failure.
   */
  async function publishViaAyrshare(platform, videoUrl, caption, ayrshareApiKey) {
    const platformMap = {
      youtube: 'youtube',
      tiktok: 'tiktok',
      facebook: 'facebook',
      instagram: 'instagram',
    };
    const ayrPlatform = platformMap[platform] || platform;

    const body = {
      post: caption || '',
      platforms: [ayrPlatform],
      mediaUrls: [videoUrl],
    };

    // Platform-specific Ayrshare fields (Req 11.2, 11.3, 11.4)
    if (platform === 'youtube') {
      body.youTubeOptions = { privacyStatus: 'private' };
    }
    if (platform === 'tiktok') {
      body.tikTokOptions = {
        privacySetting: 'SELF_ONLY',
        aiGeneratedContent: true,  // Req 11.4
      };
    }

    let resp;
    try {
      resp = await $http.request({
        method: 'POST',
        url: 'https://app.ayrshare.com/api/post',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${ayrshareApiKey}`,
        },
        body: JSON.stringify(body),
      });
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      throw new Error(`Ayrshare publish failed: ${msg}`);
    }

    const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
    if (!data || data.status === 'error' || data.errors) {
      const errMsg = (data && (data.message || JSON.stringify(data.errors))) || 'unknown error';
      throw new Error(`Ayrshare publish failed: ${errMsg}`);
    }

    // Extract Ayrshare post ID — shape varies by plan
    const postId = data.id || data.postIds?.[0] || data.postId || null;
    return { ayrshare_post_id: postId };
  }

  // ── Direct platform APIs (Req 5.10) ──────────────────────────────────────

  /**
   * Publish to YouTube Data API v3 (Req 11.2).
   * Returns { post_id: string } on success, throws on failure.
   */
  async function publishToYouTube(videoUrl, caption, auditApproved, userPrefs, credentials) {
    const accessToken = credentials.youtube_access_token || '';
    if (!accessToken) throw new Error('YouTube access token not configured');

    // Req 11.2: 'private' during audit, user preference (default 'public') post-audit
    const visibility = auditApproved
      ? (userPrefs && userPrefs.youtube_visibility) || 'public'
      : 'private';

    // Step 1: Insert video metadata (resumable upload initiation)
    const metadata = {
      snippet: {
        title: enforceCaptionLimit(caption, 'youtube') || 'AI Generated Video',
        description: '',
        tags: [],
      },
      status: { privacyStatus: visibility },
    };

    // Use videos.insert with uploadType=resumable to get upload URI
    let initResp;
    try {
      initResp = await $http.request({
        method: 'POST',
        url: 'https://www.googleapis.com/upload/youtube/v3/videos?uploadType=resumable&part=snippet,status',
        headers: {
          'Authorization': `Bearer ${accessToken}`,
          'Content-Type': 'application/json',
          'X-Upload-Content-Type': 'video/mp4',
        },
        body: JSON.stringify(metadata),
        returnFullResponse: true,
      });
    } catch (err) {
      throw new Error(`YouTube upload init failed: ${err.message || err}`);
    }

    // The upload URI comes back in the Location header
    const uploadUri = (initResp.headers && (initResp.headers.location || initResp.headers.Location)) || '';
    if (!uploadUri) throw new Error('YouTube upload init returned no upload URI');

    // Step 2: Download video bytes from videoUrl and stream to YouTube upload URI
    let videoData;
    try {
      const dlResp = await $http.request({ method: 'GET', url: videoUrl, encoding: null, returnFullResponse: true });
      videoData = dlResp.body;
    } catch (err) {
      throw new Error(`Failed to download video for YouTube upload: ${err.message || err}`);
    }

    let uploadResp;
    try {
      uploadResp = await $http.request({
        method: 'PUT',
        url: uploadUri,
        headers: {
          'Content-Type': 'video/mp4',
          'Authorization': `Bearer ${accessToken}`,
        },
        body: videoData,
        returnFullResponse: true,
      });
    } catch (err) {
      throw new Error(`YouTube video upload failed: ${err.message || err}`);
    }

    const uploadData = typeof uploadResp.body === 'string' ? JSON.parse(uploadResp.body) : uploadResp.body;
    const videoId = uploadData && uploadData.id;
    if (!videoId) throw new Error('YouTube upload returned no video ID');
    return { post_id: videoId };
  }

  /**
   * Publish to TikTok Content Posting API v2 (Req 11.3, 11.4).
   * Returns { post_id: string } on success, throws on failure.
   */
  async function publishToTikTok(videoUrl, caption, auditApproved, userPrefs, credentials) {
    const accessToken = credentials.tiktok_access_token || '';
    if (!accessToken) throw new Error('TikTok access token not configured');

    // Req 11.3: 'SELF_ONLY' during audit, user preference (default 'PUBLIC_TO_EVERYONE') post-audit
    const privacy = auditApproved
      ? (userPrefs && userPrefs.tiktok_privacy) || 'PUBLIC_TO_EVERYONE'
      : 'SELF_ONLY';

    const body = {
      post_info: {
        title: enforceCaptionLimit(caption, 'tiktok') || '',
        privacy_level: privacy,
        disable_duet: false,
        disable_comment: false,
        disable_stitch: false,
        video_cover_timestamp_ms: 0,
        // Req 11.4: AI-generated content label always required
        brand_content_toggle: false,
        brand_organic_toggle: false,
      },
      source_info: {
        source: 'PULL_FROM_URL',
        video_url: videoUrl,
      },
    };

    // TikTok v2 requires ai_generated_content flag
    body.post_info.ai_generated_content = true;  // Req 11.4

    let resp;
    try {
      resp = await $http.request({
        method: 'POST',
        url: 'https://open.tiktokapis.com/v2/post/publish/video/init/',
        headers: {
          'Content-Type': 'application/json; charset=UTF-8',
          'Authorization': `Bearer ${accessToken}`,
        },
        body: JSON.stringify(body),
      });
    } catch (err) {
      throw new Error(`TikTok publish failed: ${err.message || err}`);
    }

    const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
    if (data && data.error && data.error.code && data.error.code !== 'ok') {
      throw new Error(`TikTok publish failed: ${data.error.message || data.error.code}`);
    }
    const postId = data?.data?.publish_id || null;
    return { post_id: postId };
  }

  /**
   * Publish to Facebook as a Reel via Meta Graph API (Req 11.5).
   * Returns { post_id: string } on success, throws on failure.
   */
  async function publishToFacebook(videoUrl, caption, credentials) {
    const accessToken = credentials.facebook_access_token || '';
    const pageId = credentials.facebook_page_id || '';
    if (!accessToken) throw new Error('Facebook access token not configured');
    if (!pageId) throw new Error('Facebook page ID not configured');

    // Step 1: Initialize reel upload
    let initResp;
    try {
      initResp = await $http.request({
        method: 'POST',
        url: `https://graph.facebook.com/v19.0/${pageId}/video_reels`,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          upload_phase: 'start',
          access_token: accessToken,
        }),
      });
    } catch (err) {
      throw new Error(`Facebook Reel init failed: ${err.message || err}`);
    }
    const initData = typeof initResp === 'string' ? JSON.parse(initResp) : initResp;
    if (initData && initData.error) throw new Error(`Facebook Reel init error: ${initData.error.message || JSON.stringify(initData.error)}`);
    const videoId = initData && initData.video_id;
    const uploadUrl = initData && initData.upload_url;
    if (!videoId || !uploadUrl) throw new Error('Facebook Reel init returned no video_id or upload_url');

    // Step 2: Upload video bytes
    let videoData;
    try {
      const dlResp = await $http.request({ method: 'GET', url: videoUrl, encoding: null, returnFullResponse: true });
      videoData = dlResp.body;
    } catch (err) {
      throw new Error(`Failed to download video for Facebook upload: ${err.message || err}`);
    }

    try {
      await $http.request({
        method: 'POST',
        url: uploadUrl,
        headers: {
          'Authorization': `OAuth ${accessToken}`,
          'Content-Type': 'video/mp4',
          'offset': '0',
          'file_size': String(Buffer.isBuffer(videoData) ? videoData.length : 0),
        },
        body: videoData,
      });
    } catch (err) {
      throw new Error(`Facebook video upload failed: ${err.message || err}`);
    }

    // Step 3: Publish the reel
    const captionText = enforceCaptionLimit(caption, 'facebook');
    let publishResp;
    try {
      publishResp = await $http.request({
        method: 'POST',
        url: `https://graph.facebook.com/v19.0/${pageId}/video_reels`,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          video_id: videoId,
          upload_phase: 'finish',
          video_state: 'PUBLISHED',
          description: captionText,
          access_token: accessToken,
        }),
      });
    } catch (err) {
      throw new Error(`Facebook Reel publish failed: ${err.message || err}`);
    }
    const publishData = typeof publishResp === 'string' ? JSON.parse(publishResp) : publishResp;
    if (publishData && publishData.error) throw new Error(`Facebook Reel publish error: ${publishData.error.message || JSON.stringify(publishData.error)}`);
    return { post_id: videoId };
  }

  /**
   * Publish to Instagram as a Reel via Meta Graph API container/publish workflow (Req 11.6).
   * Returns { post_id: string } on success, throws on failure.
   */
  async function publishToInstagram(videoUrl, caption, credentials) {
    const accessToken = credentials.instagram_access_token || '';
    const igAccountId = credentials.instagram_account_id || '';
    if (!accessToken) throw new Error('Instagram access token not configured');
    if (!igAccountId) throw new Error('Instagram account ID not configured');

    // Step 1: Create media container
    const captionText = enforceCaptionLimit(caption, 'instagram');
    let containerResp;
    try {
      containerResp = await $http.request({
        method: 'POST',
        url: `https://graph.facebook.com/v19.0/${igAccountId}/media`,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          media_type: 'REELS',
          video_url: videoUrl,
          caption: captionText,
          share_to_feed: true,
          access_token: accessToken,
        }),
      });
    } catch (err) {
      throw new Error(`Instagram container creation failed: ${err.message || err}`);
    }
    const containerData = typeof containerResp === 'string' ? JSON.parse(containerResp) : containerResp;
    if (containerData && containerData.error) throw new Error(`Instagram container error: ${containerData.error.message || JSON.stringify(containerData.error)}`);
    const containerId = containerData && containerData.id;
    if (!containerId) throw new Error('Instagram container creation returned no container ID');

    // Step 2: Poll for container status until FINISHED (max 10 attempts, 6s apart)
    for (let i = 0; i < 10; i++) {
      if (i > 0) await sleep(6000);
      try {
        const statusResp = await $http.request({
          method: 'GET',
          url: `https://graph.facebook.com/v19.0/${containerId}?fields=status_code&access_token=${accessToken}`,
          headers: { 'Content-Type': 'application/json' },
        });
        const statusData = typeof statusResp === 'string' ? JSON.parse(statusResp) : statusResp;
        if (statusData && statusData.status_code === 'FINISHED') break;
        if (statusData && statusData.status_code === 'ERROR') {
          throw new Error('Instagram media container processing failed');
        }
      } catch (err) {
        if (err.message && err.message.includes('processing failed')) throw err;
        // Transient — continue polling
      }
    }

    // Step 3: Publish the container
    let publishResp;
    try {
      publishResp = await $http.request({
        method: 'POST',
        url: `https://graph.facebook.com/v19.0/${igAccountId}/media_publish`,
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          creation_id: containerId,
          access_token: accessToken,
        }),
      });
    } catch (err) {
      throw new Error(`Instagram publish failed: ${err.message || err}`);
    }
    const publishData = typeof publishResp === 'string' ? JSON.parse(publishResp) : publishResp;
    if (publishData && publishData.error) throw new Error(`Instagram publish error: ${publishData.error.message || JSON.stringify(publishData.error)}`);
    const postId = publishData && publishData.id;
    return { post_id: postId || null };
  }

  // ── Main logic ───────────────────────────────────────────────────────────

  const ctx = $input.first().json;
  const publishingPlatforms = ctx.publishing_platforms || [];
  const credentials = ctx.credentials || {};
  const internalApiUrl = ctx.internal_api_url || '';
  const articleUrl = ctx.article_url || '';
  const articleTitle = ctx.article_title || '';
  const scriptText = ctx.script_text || '';
  const openaiApiKey = credentials.openai_api_key || ($env.PLATFORM_OPENAI_API_KEY || '');
  const openaiModel = ctx.openai_model || 'gpt-4o-mini';
  const ayrshareApiKey = credentials.ayrshare_api_key || '';

  // Req 11.1: If no video URL available, skip all platforms
  const videoUrl = ctx.gdrive_link || ctx.r2_video_url || null;
  const platformResults = {};

  if (!videoUrl) {
    // Req 11.1: Record 'skipped: no video' for each platform
    for (const platform of publishingPlatforms) {
      const key = (platform || '').toLowerCase();
      platformResults[key] = {
        status: 'skipped: no video',
        post_id: null,
        ayrshare_post_id: null,
        error: null,
      };
    }

    const finalStatus = determinePublishStatus(platformResults);
    return [{
      json: {
        ...ctx,
        social_publish_results: platformResults,
        social_publish_status: finalStatus,
        stepResults: {
          ...(ctx.stepResults || {}),
          social_publish: {
            status: finalStatus,
            results: platformResults,
          }
        }
      }
    }];
  }

  // Req 11.1: Attempt publishing to each configured platform
  for (const platform of publishingPlatforms) {
    const key = (platform || '').toLowerCase();

    try {
      // Req 11.2/11.3/5.9: Query audit status at runtime
      const auditStatus = await getPlatformAuditStatus(key, internalApiUrl);
      const auditApproved = auditStatus && auditStatus.audit_approved === true;
      const userPrefs = auditStatus && auditStatus.user_preferences ? auditStatus.user_preferences : {};

      // Req 11.7: Generate AI caption (non-blocking — empty string if fails)
      const caption = await generateCaption(key, articleTitle, articleUrl, scriptText, openaiApiKey, openaiModel);

      if (!auditApproved) {
        // ── Audit period: route through Ayrshare (Req 5.9, 11.9) ──────────
        const { ayrshare_post_id } = await publishViaAyrshare(key, videoUrl, caption, ayrshareApiKey);
        platformResults[key] = {
          status: 'success',
          post_id: null,
          ayrshare_post_id,  // Req 11.9: record Ayrshare post ID
          error: null,
        };
      } else {
        // ── Post-audit: route through direct platform API (Req 5.10) ──────
        let result;
        if (key === 'youtube') {
          result = await publishToYouTube(videoUrl, caption, auditApproved, userPrefs, credentials);
        } else if (key === 'tiktok') {
          result = await publishToTikTok(videoUrl, caption, auditApproved, userPrefs, credentials);
        } else if (key === 'facebook') {
          result = await publishToFacebook(videoUrl, caption, credentials);
        } else if (key === 'instagram') {
          result = await publishToInstagram(videoUrl, caption, credentials);
        } else {
          throw new Error(`Unsupported platform: ${key}`);
        }
        platformResults[key] = {
          status: 'success',
          post_id: result.post_id || null,
          error: null,
        };
      }
    } catch (platformErr) {
      // Req 11.8: Log failure and continue to remaining platforms
      const errMsg = platformErr instanceof Error ? platformErr.message : String(platformErr);
      platformResults[key] = {
        status: 'failed',
        post_id: null,
        error: errMsg,
      };
      // Continue to next platform regardless
    }
  }

  // Req 11.10: Determine overall status
  const finalStatus = determinePublishStatus(platformResults);

  return [{
    json: {
      ...ctx,
      social_publish_results: platformResults,
      social_publish_status: finalStatus,
      stepResults: {
        ...(ctx.stepResults || {}),
        social_publish: {
          status: finalStatus,
          results: platformResults,
        }
      }
    }
  }];

} catch (error) {
  const errMsg = error instanceof Error ? error.message : String(error);
  const ctx = $input.first().json;
  return [{
    json: {
      ...ctx,
      __error: true,
      __error_step: 'Social_Publisher',
      __error_message: errMsg,
      social_publish_status: 'failed'
    }
  }];
}

// Cleanup — Requirements 10.6, 15.5
// Accepts input from either the normal flow (Social_Publisher) or the error
// branch (Error_Router). Finalizes the execution_logs record and deletes the
// R2 staged video file if it has not already been deleted.

try {
  const ctx = $input.first().json;

  // ── 1. Determine error state ──────────────────────────────────────────────

  const hadError = ctx.__error === true;
  const errorStep = ctx.__error_step || null;
  const errorMessage = ctx.__error_message || null;

  // ── 2. Best-effort R2 cleanup (Req 10.6) ─────────────────────────────────
  // Only attempt deletion if the R2 key is present and the Drive_Uploader node
  // has NOT already deleted it (drive_upload_status truthy means it ran, which
  // includes the deleteFromR2 call inside Drive_Uploader).
  // drive_upload_status falsy means Drive_Uploader never ran → delete now.

  const r2ObjectKey = ctx.r2_object_key || '';
  const driveUploaderRan = !!(ctx.drive_upload_status);

  if (r2ObjectKey && !driveUploaderRan) {
    const r2Endpoint        = (ctx.credentials && ctx.credentials.r2_endpoint)        || '';
    const r2BucketName      = (ctx.credentials && ctx.credentials.r2_bucket_name)      || '';
    const r2AccessKeyId     = (ctx.credentials && ctx.credentials.r2_access_key_id)    || '';
    const r2SecretAccessKey = (ctx.credentials && ctx.credentials.r2_secret_access_key) || '';

    if (r2Endpoint && r2BucketName && r2AccessKeyId && r2SecretAccessKey) {
      try {
        await $http.request({
          method: 'DELETE',
          url: `${r2Endpoint}/${r2BucketName}/${r2ObjectKey}`,
          auth: {
            type: 'aws',
            accessKeyId: r2AccessKeyId,
            secretAccessKey: r2SecretAccessKey,
            region: 'auto',
            service: 's3',
          },
        });
      } catch (_) {
        // Non-fatal — R2 lifecycle rule (24h) acts as fallback (Req 10.6)
      }
    }
  }

  // ── 3. Determine final pipeline status ───────────────────────────────────
  // Priority: explicit error flag > social publish outcome > success

  let finalStatus;
  let failureReason = null;

  if (hadError) {
    finalStatus = 'failed';
    failureReason = errorStep ? `[${errorStep}]: ${errorMessage}` : errorMessage;
  } else {
    const socialStatus = ctx.social_publish_status || 'success';
    if (socialStatus === 'failed') {
      finalStatus = 'failed';
      failureReason = '[Social_Publisher]: all platform publish attempts failed';
    } else if (socialStatus === 'partial') {
      finalStatus = 'partial';
      failureReason = '[Social_Publisher]: one or more platform publish attempts failed';
    } else {
      finalStatus = 'success';
    }
  }

  // ── 4. Compute timing ─────────────────────────────────────────────────────

  const endedAt = new Date().toISOString();
  const startedAt = ctx.started_at || endedAt;
  const durationMs = Math.max(0, new Date(endedAt).getTime() - new Date(startedAt).getTime());

  // ── 5. POST execution-log update to Backend API (Req 15.5) ───────────────
  // Failures here are swallowed — Cleanup must always complete.

  const internalApiUrl = ctx.internal_api_url || '';
  const executionId = ctx.execution_id || null;

  if (internalApiUrl && executionId) {
    const stepResults = ctx.stepResults || {};

    // Merge social_publish_results into stepResults.social_publish if present
    if (ctx.social_publish_results && typeof ctx.social_publish_results === 'object') {
      stepResults.social_publish = {
        status: ctx.social_publish_status || 'skipped',
        results: ctx.social_publish_results,
      };
    }

    const updateBody = JSON.stringify({
      execution_id: executionId,
      status: finalStatus,
      ended_at: endedAt,
      duration_ms: durationMs,
      failure_reason: failureReason,
      step_results: stepResults,
    });

    try {
      await $http.request({
        method: 'POST',
        url: `${internalApiUrl}/internal/execution-log/update`,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${$env.N8N_SERVICE_TOKEN || ''}`,
        },
        body: updateBody,
        options: { response: { response: { neverError: true } } },
      });
    } catch (_) {
      // Non-fatal — dashboard will show partial data but execution continues
    }
  }

  // ── 6. Return context for Notify node ────────────────────────────────────

  return [{
    json: {
      ...ctx,
      __cleanup_done: true,
      final_status: finalStatus,
      failure_reason: failureReason,
      ended_at: endedAt,
      duration_ms: durationMs,
    }
  }];

} catch (error) {
  // Catch-all: Cleanup must never crash the workflow
  const errMsg = error instanceof Error ? error.message : String(error);
  const ctx = $input.first().json;
  return [{
    json: {
      ...ctx,
      __cleanup_done: true,
      __cleanup_error: errMsg,
      final_status: ctx.final_status || 'failed',
      failure_reason: ctx.failure_reason || `[Cleanup]: ${errMsg}`,
    }
  }];
}

// Error_Router: receives n8n error output from any node,
// injects __error fields, and passes to Cleanup + Notify.
try {
  const item = $input.first();
  const err = item.error || {};
  const ctx = item.json || {};

  return [{
    json: {
      ...ctx,
      __error: true,
      __error_step: err.node || 'Unknown',
      __error_message: err.message || 'Unknown error',
      final_status: 'failed'
    }
  }];
} catch (e) {
  return [{
    json: {
      __error: true,
      __error_step: 'Error_Router',
      __error_message: String(e),
      final_status: 'failed',
      execution_id: null,
      pipeline_id: null,
      user_id: null,
      internal_api_url: ''
    }
  }];
}
